struct HashtableHandleMap {
    const jass::StableHandleMap& convert;const jass::Module& module;
    std::map<std::pair<jass::Id,std::uint32_t>,std::uint32_t> mapped;
    std::multimap<std::uint32_t,std::pair<jass::Id,std::uint32_t>> byInput,byOutput;
    bool related(jass::Id a,jass::Id b) const {return module.assignable(a,b) || module.assignable(b,a);}
    std::uint32_t operator()(jass::Id type,std::uint32_t id){if(!convert)throw std::runtime_error("Hashtable snapshot requires a handle mapping");auto key=std::pair{type,id};if(auto found=mapped.find(key);found!=mapped.end())return found->second;auto value=convert(module.type(type).name,id);if(!value)throw std::runtime_error("Invalid hashtable handle mapping");auto [first,last]=byInput.equal_range(id);for(;first!=last;++first)if(related(type,first->second.first) && value!=first->second.second)throw std::runtime_error("Conflicting hashtable handle mapping");auto [begin,end]=byOutput.equal_range(value);for(;begin!=end;++begin)if(related(type,begin->second.first) && id!=begin->second.second)throw std::runtime_error("Conflicting hashtable handle mapping");mapped.emplace(key,value);byInput.emplace(id,std::pair{type,value});byOutput.emplace(value,std::pair{type,id});return value;}
};
