Bytes ScriptSession::encodeHashtables(const jass::StableHandleMap& encodeHandle) const {
    if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Hashtable snapshot requires a quiescent local session");constexpr size_t budget=128u*1024u*1024u,limit=1048576;std::vector<std::uint32_t> handles;for(size_t i=0;i<objects_.size();++i)if(objects_[i].kind==NativeKind::Hashtable)handles.push_back(handleBase+std::uint32_t(i));if(handles.size()>65536 || (!handles.empty() && !encodeHandle))throw std::runtime_error("Hashtable snapshot requires valid mapping and budget");auto& module=runtime_.module();HashtableHandleMap convert{encodeHandle,module};std::map<std::uint32_t,std::uint32_t> stable;std::set<std::uint32_t> used;for(auto id:handles){auto mapped=convert(module.typeId("hashtable"),id);if(!mapped || !used.insert(mapped).second || !objects_[id-handleBase].alive)throw std::runtime_error("Invalid hashtable identity");stable.emplace(id,mapped);}SnapshotWriter out(budget-64);out.u32(tag("SHTB"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));auto& sources=module.program().sources();if(sources.size()>4096)throw std::runtime_error("Hashtable source count exceeds budget");out.size(sources.size());for(auto& source:sources){out.text(source.name,65536);out.text(sha256({reinterpret_cast<const std::uint8_t*>(source.text.data()),source.text.size()}),64);}out.size(handles.size());size_t total=0;
    for(auto id:handles){auto table=std::get<std::shared_ptr<ScriptHashtable>>(objects_[id-handleBase].state);if(!table || table->values.size()>131072 || table->values.size()>limit-total)throw std::runtime_error("Hashtable values exceed budget");total+=table->values.size();out.u32(stable.at(id));out.size(table->values.size());for(auto& [key,value]:table->values){auto& [parent,child,kind]=key;out.u32(parent);out.u32(child);unsigned category=kind=="integer"?0:kind=="real"?1:kind=="boolean"?2:kind=="string"?3:kind=="handle"?4:5;if(category>4 || value.type>=module.types().size() || value.codeOwner)throw std::runtime_error("Invalid hashtable value");out.u32(category);auto& type=module.type(value.type);if(category<4){const char* expected[]={"integer","real","boolean","string"};if(type.name!=expected[category] || (category!=3 && value.text) || (category==2 && value.bits>1) || (category==3 && value.bits))throw std::runtime_error("Invalid hashtable primitive");if(category==3){out.u32(value.text?1:0);if(value.text)out.text(*value.text,16u*1024u*1024u);}else out.u32(value.bits);}else{if(type.category!=jass::Category::Handle || value.text)throw std::runtime_error("Invalid hashtable handle type");out.text(type.name,1024);auto nested=stable.find(value.bits);bool local=value.bits && nested!=stable.end();out.u32(local?1:0);if(!value.bits)out.u32(0);else{auto mapped=convert(value.type,value.bits);if(!mapped || (local && (mapped!=nested->second || !module.assignable(value.type,module.typeId("hashtable")))))throw std::runtime_error("Invalid hashtable handle mapping");out.u32(mapped);}}}}return sealSnapshot(out.finish(),budget);
}
std::map<std::uint32_t,std::uint32_t> ScriptSession::rebuildHashtables(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || hashtablesRebuilt_ || std::any_of(objects_.begin(),objects_.end(),[](const auto& object){return object.kind==NativeKind::Hashtable;}) || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Hashtable rebuild requires a fresh quiescent local session before map main");constexpr size_t budget=128u*1024u*1024u,limit=1048576;Binary in(openSnapshot(bytes,budget));in.expect(tag("SHTB"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Hashtable snapshot map or clock mismatch");struct Entry{std::uint32_t parent,child;unsigned category;std::string type;std::uint32_t bits=0;bool local=false;std::optional<std::string> text;};struct Table{std::uint32_t id;std::vector<Entry> values;};std::vector<Table> saved;std::set<std::uint32_t> stable;auto& module=runtime_.module();auto& sources=module.program().sources();auto sourceCount=in.u32();if(sourceCount!=sources.size() || sourceCount>4096)throw std::runtime_error("Hashtable snapshot source differs");for(auto& source:sources)if(snapshotText(in,65536)!=source.name || snapshotText(in,64)!=sha256({reinterpret_cast<const std::uint8_t*>(source.text.data()),source.text.size()}))throw std::runtime_error("Hashtable snapshot source differs");auto count=in.u32();if(count>65536)throw std::runtime_error("Hashtable count exceeds budget");size_t total=0;HashtableHandleMap convert{decodeHandle,module};for(unsigned i=0;i<count;++i){Table table{};table.id=in.u32();auto entries=in.u32();if(!table.id || !stable.insert(table.id).second || entries>131072 || entries>limit-total)throw std::runtime_error("Invalid hashtable identity or count");total+=entries;std::set<std::tuple<std::uint32_t,std::uint32_t,unsigned>> keys;for(unsigned j=0;j<entries;++j){Entry entry{};entry.parent=in.u32();entry.child=in.u32();entry.category=in.u32();if(entry.category>4 || !keys.emplace(entry.parent,entry.child,entry.category).second)throw std::runtime_error("Invalid hashtable key");if(entry.category<3){entry.bits=in.u32();if(entry.category==2 && entry.bits>1)throw std::runtime_error("Invalid hashtable boolean");}else if(entry.category==3){auto present=in.u32();if(present>1)throw std::runtime_error("Invalid hashtable string");if(present)entry.text=snapshotText(in,16u*1024u*1024u);}else{entry.type=snapshotText(in,1024);auto type=module.typeId(entry.type),local=in.u32();entry.bits=in.u32();if(type==jass::none || module.type(type).category!=jass::Category::Handle || local>1 || (local && (!entry.bits || !module.assignable(type,module.typeId("hashtable")))))throw std::runtime_error("Invalid hashtable handle");entry.local=local!=0;if(entry.bits && !entry.local){entry.bits=convert(type,entry.bits);if(entry.type=="unit" || entry.type=="item" || entry.type=="destructable" || entry.type=="widget"){if(entry.bits<handleBase || entry.bits-handleBase>=objects_.size())throw std::runtime_error("Invalid hashtable widget mapping");auto kind=objects_[entry.bits-handleBase].kind;bool match=entry.type=="unit"?kind==NativeKind::Unit:entry.type=="item"?kind==NativeKind::Item:entry.type=="destructable"?kind==NativeKind::Destructable:kind==NativeKind::Unit || kind==NativeKind::Item || kind==NativeKind::Destructable;if(!match)throw std::runtime_error("Invalid hashtable widget mapping");}}}table.values.push_back(std::move(entry));}saved.push_back(std::move(table));}in.finish();for(auto& table:saved)for(auto& entry:table.values)if(entry.local && !stable.contains(entry.bits))throw std::runtime_error("Missing nested hashtable identity");
    struct Guard{bool& failed;bool done=false;~Guard(){if(!done)failed=true;}}guard{failed_};std::map<std::uint32_t,std::uint32_t> result;for(auto& table:saved){auto handle=create(NativeKind::Hashtable);result.emplace(table.id,handle.bits);}const char* kinds[]={"integer","real","boolean","string","handle"};for(auto& table:saved){auto state=std::get<std::shared_ptr<ScriptHashtable>>(objects_[result.at(table.id)-handleBase].state);for(auto& entry:table.values){jass::Value value;if(entry.category==0)value=runtime_.integer(std::bit_cast<std::int32_t>(entry.bits));else if(entry.category==1)value=runtime_.real(jass::Real::fromBits(entry.bits));else if(entry.category==2)value=runtime_.boolean(entry.bits!=0);else if(entry.category==3)value=entry.text?runtime_.string(*entry.text):jass::Value{module.typeId("string"),0,{}};else value=runtime_.handle(entry.type,entry.local?result.at(entry.bits):entry.bits);state->values.emplace(std::tuple{entry.parent,entry.child,std::string(kinds[entry.category])},std::move(value));}}hashtablesRebuilt_=true;guard.done=true;return result;
}
void ScriptSession::bindHashtableNatives() {
    auto table=[this](jass::Value value){return std::get<std::shared_ptr<ScriptHashtable>>(object(value,NativeKind::Hashtable).state);};
    bind("InitHashtable","hashtable",{},[this](auto&,auto){return create(NativeKind::Hashtable);});
    auto store=[table](auto& vm,auto a,const std::string& type,bool result){auto state=table(a[0]);auto key=std::make_tuple(a[1].bits,a[2].bits,type);if(state->values.size()>=131072 && !state->values.contains(key))throw std::runtime_error("Hashtable value budget exceeded");state->values[key]=a[3];return result?vm.boolean(true):vm.nothing();};
    for(auto [suffix,type]:std::initializer_list<std::pair<const char*,const char*>>{{"Integer","integer"},{"Real","real"},{"Boolean","boolean"},{"Str","string"}}){
        bind((std::string("Save")+suffix).c_str(),std::string_view(type)=="string"?"boolean":"nothing",{"hashtable","integer","integer",type},[store,type](auto& vm,auto a){return store(vm,a,type,std::string_view(type)=="string");});
        bind((std::string("Load")+suffix).c_str(),type,{"hashtable","integer","integer"},[table,type](auto& vm,auto a){auto state=table(a[0]);auto found=state->values.find({a[1].bits,a[2].bits,type});return found==state->values.end()?jass::Value{vm.module().typeId(type),0,{}}:found->second;});
    }
    for(auto [suffix,type]:std::initializer_list<std::pair<const char*,const char*>>{{"Integer","integer"},{"Real","real"},{"Boolean","boolean"},{"String","string"},{"Handle","handle"}}){bind((std::string("HaveSaved")+suffix).c_str(),"boolean",{"hashtable","integer","integer"},[table,type](auto& vm,auto a){return vm.boolean(table(a[0])->values.contains({a[1].bits,a[2].bits,type}));});bind((std::string("RemoveSaved")+suffix).c_str(),"nothing",{"hashtable","integer","integer"},[table,type](auto& vm,auto a){table(a[0])->values.erase({a[1].bits,a[2].bits,type});return vm.nothing();});}
    auto& module=runtime_.module();for(size_t i=0;i<module.program().functions().size();++i){auto& source=module.program().functions()[i];if(!source.native || !source.name.ends_with("Handle"))continue;auto& signature=module.functions()[i];if(source.name.starts_with("Save") && signature.parameters.size()==4 && module.type(signature.parameters[0]).name=="hashtable"){auto type=module.type(signature.parameters[3]).name;if(module.type(signature.parameters[3]).category!=jass::Category::Handle)continue;bind(source.name.c_str(),"boolean",{"hashtable","integer","integer",type.c_str()},[store](auto& vm,auto a){return store(vm,a,"handle",true);});}
        else if(source.name.starts_with("Load") && signature.parameters.size()==3 && module.type(signature.parameters[0]).name=="hashtable" && module.type(signature.result).category==jass::Category::Handle){auto type=module.type(signature.result).name;bind(source.name.c_str(),type.c_str(),{"hashtable","integer","integer"},[this,table,type](auto& vm,auto a){auto state=table(a[0]);auto found=state->values.find({a[1].bits,a[2].bits,"handle"});if(found==state->values.end())return vm.handle(type,0);auto value=found->second;auto wanted=vm.module().typeId(type);if(vm.module().assignable(wanted,value.type))return vm.handle(type,value.bits);if(value.bits>=handleBase && value.bits-handleBase<objects_.size()){auto kind=objects_[value.bits-handleBase].kind;const char* dynamic=nullptr;switch(kind){case NativeKind::Trackable:dynamic="trackable";break;case NativeKind::Ubersplat:dynamic="ubersplat";break;case NativeKind::Image:dynamic="image";break;case NativeKind::UnitPool:dynamic="unitpool";break;case NativeKind::ItemPool:dynamic="itempool";break;case NativeKind::TextTag:dynamic="texttag";break;case NativeKind::Multiboard:dynamic="multiboard";break;case NativeKind::MultiboardItem:dynamic="multiboarditem";break;case NativeKind::Leaderboard:dynamic="leaderboard";break;case NativeKind::Lightning:dynamic="lightning";break;case NativeKind::Effect:dynamic="effect";break;case NativeKind::Ability:dynamic="ability";break;case NativeKind::Dialog:dynamic="dialog";break;case NativeKind::Button:dynamic="button";break;case NativeKind::DefeatCondition:dynamic="defeatcondition";break;case NativeKind::Destructable:dynamic="destructable";break;case NativeKind::Unit:dynamic="unit";break;case NativeKind::Item:dynamic="item";break;case NativeKind::Player:dynamic="player";break;case NativeKind::Group:dynamic="group";break;case NativeKind::Timer:dynamic="timer";break;case NativeKind::Trigger:dynamic="trigger";break;case NativeKind::Location:dynamic="location";break;case NativeKind::Rect:dynamic="rect";break;case NativeKind::Sound:dynamic="sound";break;case NativeKind::Weather:dynamic="weathereffect";break;case NativeKind::Force:dynamic="force";break;case NativeKind::Boolean:dynamic="boolexpr";break;case NativeKind::Action:dynamic="triggeraction";break;case NativeKind::Condition:dynamic="triggercondition";break;case NativeKind::Event:dynamic="event";break;case NativeKind::TimerDialog:dynamic="timerdialog";break;case NativeKind::Region:dynamic="region";break;case NativeKind::Fog:dynamic="fogmodifier";break;case NativeKind::Cache:dynamic="gamecache";break;case NativeKind::Hashtable:dynamic="hashtable";break;default:break;}if(dynamic && vm.module().assignable(wanted,vm.module().typeId(dynamic)))return vm.handle(type,value.bits);}return vm.handle(type,0);});}}
    bind("FlushChildHashtable","nothing",{"hashtable","integer"},[table](auto& vm,auto a){auto state=table(a[0]);std::erase_if(state->values,[&](auto& value){return std::get<0>(value.first)==a[1].bits;});return vm.nothing();});
    bind("FlushParentHashtable","nothing",{"hashtable"},[table](auto& vm,auto a){table(a[0])->values.clear();return vm.nothing();});
}
